def transform(grid):
    from collections import Counter
    R, C = len(grid), len(grid[0])
    cnt = Counter(v for row in grid for v in row)
    bg = cnt.most_common(1)[0][0]
    marks = [v for v in cnt if v != bg]
    mark = marks[0] if len(marks) == 1 else max(marks, key=lambda v: cnt[v])
    cells = [(r, c) for r in range(R) for c in range(C) if grid[r][c] == mark]
    rs = [r for r, c in cells]
    cs = [c for r, c in cells]
    r0, r1, c0, c1 = min(rs), max(rs), min(cs), max(cs)
    fill = 2
    if fill in (bg, mark):
        fill = next(v for v in range(10) if v not in (bg, mark))
    out = [row[:] for row in grid]
    for c in range(c0, c1 + 1):
        for r in (r0, r1):
            if out[r][c] != mark:
                out[r][c] = fill
    for r in range(r0, r1 + 1):
        for c in (c0, c1):
            if out[r][c] != mark:
                out[r][c] = fill
    return out
